import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';

// News & Events — one Markdown file per article in src/content/news/.
// Files are generated by scripts/import-news.mjs; raw HTML is not allowed in
// the body (the importer strips it and rehype-sanitize enforces it at render).
const news = defineCollection({
  loader: glob({ pattern: '*.md', base: './src/content/news' }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    pubDate: z.coerce.date(),
    heroImage: z.string().optional(),
    heroImageAlt: z.string().optional(),
    sourceUrl: z.string().url().optional(),
  }),
});

export const collections = { news };
